// @pit: {"label": "Build five analog charts, write report markdown and CSV data to docs/research"}
async ({ http: { request }, chart: { xy }, workspace: { edit } }) => {
  const H = { "User-Agent": "Mozilla/5.0" };
  const yURL = (s: string) => `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?period1=473385600&period2=1794787200&interval=1mo`;
  const fURL = (id: string) => `https://fred.stlouisfed.org/graph/fredgraph.csv?id=${id}`;
  const capeURL = "https://www.multpl.com/shiller-pe/table/by-month";
  const get = (u: string) => request(u, { maxBytes: 1_000_000, headers: H }).then((r) => r.body);
  const [sB, nB, ffB, tB, cB] = await Promise.all([get(yURL("^GSPC")), get(yURL("^IXIC")), get(fURL("FEDFUNDS")), get(fURL("GS10")), get(capeURL)]);
  const py = (b: string) => { const j = JSON.parse(b).chart.result[0]; const o: Record<string, number> = {}; j.timestamp.forEach((t: number, i: number) => { const c = j.indicators.quote[0].close[i]; if (c != null) o[new Date(t * 1000 + 86400000 * 3).toISOString().slice(0, 7)] = c; }); return o; };
  const pf = (b: string) => Object.fromEntries(b.trim().split("\n").slice(1).map((l) => [l.slice(0, 7), +l.split(",")[1]])) as Record<string, number>;
  const spx = py(sB), ndx = py(nB), ff = pf(ffB), t10 = pf(tB);
  const txt = cB.replace(/<[^>]+>/g, " ").replace(/&#x2002;/g, " ").replace(/\s+/g, " ");
  const cape: Record<string, number> = {}; for (const mm of txt.matchAll(/([A-Z][a-z]{2}) (\d{1,2}), (\d{4}) (\d+\.\d+)/g)) { const mo = "JanFebMarAprMayJunJulAugSepOctNovDec".indexOf(mm[1]) / 3 + 1; const k = `${mm[3]}-${String(mo).padStart(2, "0")}`; if (!(k in cape)) cape[k] = +mm[4]; }
  const capeVals = Object.values(cape).sort((a, b) => a - b); const capeMedian = capeVals[Math.floor(capeVals.length / 2)];
  const months = Object.keys(spx).sort();
  const add = (k: string, n: number) => { const [y, m] = k.split("-").map(Number); const t = y * 12 + (m - 1) + n; return `${Math.floor(t / 12)}-${String((t % 12) + 1).padStart(2, "0")}`; };
  const r1 = (x: number) => Math.round(x * 10) / 10;
  const srcY = ["https://finance.yahoo.com/quote/%5EGSPC/history", "https://finance.yahoo.com/quote/%5EIXIC/history"];
  // Chart 1: Netscape vs ChatGPT overlay
  const A = "1995-08", B = "2022-11", N = 49;
  const ks = Array.from({ length: N }, (_, k) => k);
  const reb = (o: Record<string, number>, s: string) => ks.map((k) => r1((o[add(s, k)] / o[s]) * 100));
  const c1 = await xy({ title: "Rebased to 100: Netscape IPO (Aug 1995) vs ChatGPT launch (Nov 2022)", x: ks.map((k) => `M${k}`),
    series: [{ name: "S&P 500, Aug 1995–Aug 1999", values: reb(spx, A) }, { name: "S&P 500, Nov 2022–Nov 2026", values: reb(spx, B) }, { name: "Nasdaq Composite, Aug 1995–Aug 1999", values: reb(ndx, A) }, { name: "Nasdaq Composite, Nov 2022–Nov 2026", values: reb(ndx, B) }],
    yLabel: "Index (start = 100)", scale: "none", decimals: 0, maxPoints: 49, source: srcY });
  // Chart 2: analog-implied S&P path from today
  const now = "2026-11", L = 49, today = spx[now];
  const imp = (s: string) => Array.from({ length: L }, (_, k) => Math.round(today * spx[add(s, k)] / spx[s]));
  const c2 = await xy({ title: "If 1999–2003 repeated from today: implied S&P 500 path (illustration, not a forecast)", x: Array.from({ length: L }, (_, k) => add(now, k)),
    series: [{ name: "Netscape alignment (today = Aug 1999)", values: imp("1999-08") }, { name: "Best-fit alignment (today = Feb 1998)", values: imp("1998-02") }, { name: "S&P 500 today (7,562)", values: Array(L).fill(Math.round(today)) }],
    yLabel: "S&P 500", scale: "none", decimals: 0, maxPoints: 49, source: srcY });
  // Chart 3: CAPE
  const cK = Object.keys(cape).filter((k) => k >= "1990-01" && /-(01|04|07|10)$/.test(k)).sort(); if (!cK.includes(now)) cK.push(now);
  const c3 = await xy({ title: "Shiller CAPE (cyclically adjusted P/E), 1990–2026", x: cK, series: [{ name: "S&P 500 CAPE", values: cK.map((k) => cape[k]) }, { name: "Dot-com peak (44.2, Dec 1999)", values: cK.map(() => 44.2) }, { name: `Long-run median since 1871 (${capeMedian})`, values: cK.map(() => capeMedian) }],
    yLabel: "CAPE", unit: "x", scale: "none", decimals: 1, maxPoints: 75, yMin: 0, source: capeURL });
  // Chart 4: rolling returns
  const rK = months.filter((k) => k >= "1990-01" && /-(01|07)$/.test(k)); if (!rK.includes(now)) rK.push(now);
  const cagr = (k: string, y: number) => r1(((spx[k] / spx[add(k, -12 * y)]) ** (1 / y) - 1) * 100);
  const c4 = await xy({ title: "S&P 500 trailing annualized price return, 1990–2026", x: rK, series: [{ name: "Trailing 3-year", values: rK.map((k) => cagr(k, 3)) }, { name: "Trailing 5-year", values: rK.map((k) => cagr(k, 5)) }],
    yLabel: "Annualized return", unit: "%", scale: "none", decimals: 0, maxPoints: 75, source: srcY[0] });
  // Chart 5: rates aligned
  const R = 48; const rk = Array.from({ length: R }, (_, k) => k);
  const c5 = await xy({ title: "Rates on the same clock: months since Netscape IPO vs since ChatGPT", x: rk.map((k) => `M${k}`),
    series: [{ name: "10-yr Treasury, 1995–99", values: rk.map((k) => t10[add(A, k)]) }, { name: "10-yr Treasury, 2022–26", values: rk.map((k) => t10[add(B, k)] ?? null) }, { name: "Fed funds, 1995–99", values: rk.map((k) => ff[add(A, k)]) }, { name: "Fed funds, 2022–26", values: rk.map((k) => ff[add(B, k)] ?? null) }],
    yLabel: "Yield", unit: "%", scale: "none", decimals: 1, maxPoints: 48, yMin: 0, source: [fURL("GS10"), fURL("FEDFUNDS")] });
  // CSV
  const csv = ["month,sp500_close,nasdaq_close,cape,fed_funds,treasury_10y", ...months.filter((k) => k >= "1990-01").map((k) => [k, spx[k]?.toFixed(2) ?? "", ndx[k]?.toFixed(2) ?? "", cape[k] ?? "", ff[k] ?? "", t10[k] ?? ""].join(","))].join("\n") + "\n";
  await edit("docs/research/data/dotcom-analog-monthly.csv", { revision: null, changes: [{ kind: "replaceFile", content: csv }] });
  await edit("/tmp/charts.json", { revision: null, changes: [{ kind: "replaceFile", content: JSON.stringify({ c1: c1.markdown, c2: c2.markdown, c3: c3.markdown, c4: c4.markdown, c5: c5.markdown }) }] });
  const impA = imp("1999-08"), impB = imp("1998-02");
  const ext = (a: number[]) => { const mx = Math.max(...a), mn = Math.min(...a.slice(a.indexOf(mx))); return { peak: mx, peakAt: add(now, a.indexOf(mx)), trough: mn, troughAt: add(now, a.indexOf(mn)) }; };
  return { capeMedian, capeNow: cape[now], dropped: [c1.dropped, c2.dropped, c3.dropped, c4.dropped, c5.dropped], points: [c1.points, c2.points, c3.points, c4.points, c5.points], extA: ext(impA), extB: ext(impB), c1cap: c1.caption, c5cap: c5.caption, len: [c1.markdown.length, c2.markdown.length, c3.markdown.length, c4.markdown.length, c5.markdown.length] } as PitJsonValue;
}
